#!/usr/bin/env Rscript
source(file.path(dirname(sub("^--file=","",commandArgs(FALSE)[grepl("^--file=",commandArgs(FALSE))])),"common.R"))
fc<-file.path(tempdir(),'font_cache');dir.create(fc,showWarnings=FALSE);Sys.setenv(XDG_CACHE_HOME=fc)
suppressPackageStartupMessages({library(ggplot2);library(patchwork);library(stringr)})
stopifnot(all(fread(file.path(out,'results/tables/02_selection_checks.csv'))$pass))
hi<-'#BC496B';lo<-'#327F94';ink<-'#223543';gray<-'#65737D';pal<-c('#D3E6EA','#62A7BA','#286886','#182E52')
fmt<-function(x)ifelse(is.na(x),'NE',ifelse(x<.001,formatC(x,format='e',digits=1),formatC(x,format='f',digits=3)))
base<-theme_classic(base_size=11,base_family='Arial')+theme(axis.text=element_text(colour=ink),axis.title=element_text(colour=ink),plot.title=element_text(face='bold',colour=ink,size=15),plot.subtitle=element_text(size=10.5,colour=gray,lineheight=1.15),plot.caption=element_text(size=9,colour=gray,hjust=0,lineheight=1.2),legend.position='bottom',legend.title=element_text(size=10,margin=margin(r=7)),legend.text=element_text(size=9.5),plot.margin=margin(10,15,10,10))
ann<-theme(plot.title=element_text(family='Arial',face='bold',size=17,colour=ink),plot.subtitle=element_text(family='Arial',size=11,colour=gray,margin=margin(t=5,b=8)),plot.caption=element_text(family='Arial',size=9,colour=gray,hjust=0,lineheight=1.15,margin=margin(t=8)),plot.margin=margin(14,16,12,16))
savefig<-function(p,n,w,h){ggsave(file.path(out,'results/figures',paste0(n,'.png')),p,width=w,height=h,dpi=600,device=ragg::agg_png,bg='white');ggsave(file.path(out,'results/figures',paste0(n,'.pdf')),p,width=w,height=h,device=cairo_pdf,bg='white');ggsave(file.path(out,'results/figures',paste0(n,'.svg')),p,width=w,height=h,device=grDevices::svg,bg='white');cat('SAVED',n,w,h,'\n')}
label<-function(x){s<-str_to_sentence(gsub('_',' ',sub('^GOBP_','',x)));s<-gsub('\\bdna\\b','DNA',s,ignore.case=TRUE);s<-gsub('\\brna\\b','RNA',s,ignore.case=TRUE);s<-gsub('\\bmrna\\b','mRNA',s,ignore.case=TRUE);s<-gsub('\\brrna\\b','rRNA',s,ignore.case=TRUE);s<-gsub('\\bb cell\\b','B cell',s,ignore.case=TRUE);s<-gsub('\\bpoly a\\b','poly(A)',s,ignore.case=TRUE);str_wrap(s,width=34)}
d<-fread(file.path(out,'results/tables/plotdata_GO_overviews.csv'));d[,':='(display_label=label(pathway),neglog10q=-log10(q_global),absNES=abs(NES),display_y=9-display_order)]
# --cd8-only redraws only the two author-selected figures; tables/inference stay frozen.
cd8_only <- '--cd8-only' %in% commandArgs(TRUE)
cts<-c('CD8','cDC1');titles<-c(CD8='CD8⁺ T-cell pathways',cDC1='cDC1-like pathways')
# Same color, point-area and x-axis scales across both GO figures.
qmax<-ceiling(max(d$neglog10q));xmax<-ceiling(max(d$absNES)*2)/2+.15
sb<-unique(floor(seq(min(d$leading_edge_n),max(d$leading_edge_n),length.out=3)/5)*5);sb<-sb[sb>0];sizelim<-c(0,max(d$leading_edge_n))
for(ct in if(cd8_only)'CD8' else cts){
 parts<-lapply(c('High','Low'),function(dr){dd<-copy(d[cell_type==ct&direction==dr]);setorder(dd,display_order);col<-if(dr=='High')hi else lo
  if(!nrow(dd))return(ggplot()+annotate('text',x=0,y=0,label='No GO:BP terms meet\nglobal BH q < 0.05',family='Arial',colour=gray,size=4)+theme_void()+labs(title=paste0('Degradation-',dr)))
  p<-ggplot(dd,aes(x=absNES,y=display_y))+geom_segment(aes(x=0,xend=absNES,yend=display_y),colour='#DCE5EB',linewidth=.6)+geom_point(aes(fill=neglog10q,size=leading_edge_n),shape=21,colour='white',stroke=.45)+scale_y_continuous(breaks=dd$display_y,labels=dd$display_label,limits=c(.4,8.65),expand=expansion(mult=0))+scale_x_continuous(limits=c(0,xmax),breaks=seq(0,floor(xmax),1),expand=expansion(mult=c(0,.04)))+scale_fill_gradientn(colours=pal,limits=c(0,qmax),name='−log10(global BH q)',guide=guide_colorbar(order=1,barwidth=unit(35,'mm'),barheight=unit(2.5,'mm')))+scale_size_area(max_size=6,limits=sizelim,breaks=sb,name='Leading-edge genes',guide=guide_legend(order=2,override.aes=list(fill='#608A9F',colour='white')))+labs(title=paste0('Degradation-',dr),subtitle=if(dr=='High')'Enriched toward higher degradation expression' else 'Enriched toward lower degradation expression',x='Enrichment strength |NES|',y=NULL)+base+theme(axis.line.y=element_blank(),axis.ticks.y=element_blank(),axis.text.y=element_text(size=10.5,lineheight=1.03,margin=margin(r=9)),axis.line.x=element_line(colour='#9FAAB1',linewidth=.35),axis.ticks.x=element_line(colour='#9FAAB1'),plot.title=element_text(colour=col,size=15),legend.margin=margin(4,6,4,6))
  if(nrow(dd)<8)p<-p+annotate('text',x=xmax/2,y=2.4,label=paste0('All ',nrow(dd),' qualifying terms shown'),family='Arial',colour=gray,size=3.4)
  p
 })
 subtitle<-if(ct=='CD8')'Fixed whole-tumour groups  |  Post-treatment NSCLC  |  High n = 7, Low n = 5  |  16,229 CD8⁺ T cells' else 'Fixed whole-tumour groups  |  Post-treatment NSCLC  |  High n = 6, Low n = 4  |  111 cDC1-like cells'
 cap<-paste0('Patient-by-cell-type pseudobulk; histology-adjusted GSEA; global BH across 5,959 cell-type × gene-set tests.\nUp to eight significant GO:BP terms per direction, with gene-overlap filtering. ',if(ct=='cDC1')'Exploratory: only 5–22 cells per eligible patient.' else 'Gene-set names do not establish a cell-specific function.')
 p<-(parts[[1]]|parts[[2]])+plot_layout(guides='collect')+plot_annotation(title=paste0(titles[ct],' by tumour sarcosine-degradation expression'),subtitle=subtitle,caption=cap,theme=ann)&theme(legend.position='bottom')
 savefig(p,paste0('Fig8_',ct,'_GO_Overview'),12.4,7.1)
}
# Display tables remain the original frozen selection, including historical cDC1 rows.
e<-fread(file.path(out,'results/tables/plotdata_Exact_Fig7_Pathways.csv'));e[,':='(display_y=5-display_order,significant=q_global<.05,q_label=fmt(q_global))]
lab4<-c('APC cross-presentation','TCR signaling','TNFR2-related\nnoncanonical NF-κB','IFN-γ response')
parts<-lapply('CD8',function(ct){dd<-e[cell_type==ct];dd[,point_fill:=ifelse(significant,ifelse(NES>0,hi,lo),'white')];dd[,point_line:=ifelse(NES>0,hi,lo)]
 ggplot(dd,aes(NES,display_y))+geom_vline(xintercept=0,colour='#ACB8C0',linewidth=.4,linetype='dashed')+geom_segment(aes(x=0,xend=NES,yend=display_y),colour='#D6E0E6',linewidth=.8)+geom_point(aes(fill=point_fill,colour=point_line),shape=21,size=4.4,stroke=.9)+scale_fill_identity()+scale_colour_identity()+geom_text(aes(x=3.27,label=q_label),hjust=0,family='Arial',colour=ink,size=3.65)+annotate('text',x=3.27,y=4.68,label='Global BH q',hjust=0,family='Arial',colour=gray,size=3.3)+scale_y_continuous(breaks=4:1,labels=lab4,limits=c(.55,4.92),expand=expansion(mult=0))+scale_x_continuous(breaks=-1:3,expand=expansion(mult=0))+coord_cartesian(xlim=c(-1,3),clip='off')+labs(title='Four immune programs in CD8⁺ T cells',subtitle='Whole-tumour Degradation groups  |  Post-treatment NSCLC\nHigh n = 7, Low n = 5  |  16,229 CD8⁺ T cells',x='NES (High − Low)',y=NULL)+base+theme(axis.line.y=element_blank(),axis.ticks.y=element_blank(),axis.text.y=element_text(size=11,margin=margin(r=8)),plot.margin=margin(10,75,10,8),plot.title=element_text(size=15))
})
p<-parts[[1]]+labs(caption='Patient-level pseudobulk; histology-adjusted GSEA. Positive NES: Degradation-High.\nFilled points: global BH q < 0.05; open points: q ≥ 0.05.\nOriginal BH family retained: 5,959 cell-type × gene-set tests; only CD8⁺ T cells displayed.\nCAMERA and primary patient-score tests are nonsignificant for all four pathways.')+theme(plot.title=element_text(size=16),plot.subtitle=element_text(size=10.5,margin=margin(t=5,b=10)),plot.caption=element_text(size=8.4,margin=margin(t=14)),plot.caption.position='plot',plot.title.position='plot',plot.margin=margin(15,82,13,16))
savefig(p,'Fig8_CellType_Exact_Immune_Pathways',8.8,5.7)
if(cd8_only){capture.output(sessionInfo(),file=file.path(out,'logs/sessionInfo_plot.txt'));quit(save='no')}
# Patient dots and model intervals expose the nonsignificant score tests.
v<-fread(file.path(out,'results/tables/plotdata_Patient_Scores.csv'));v[,group:=factor(group,levels=c('Low','High'))]
plots<-list()
for(ct in cts)for(i in 1:4){id<-focus$pathway[i];z<-e[cell_type==ct&pathway==id];dd<-v[cell_type==ct&pathway==id]
 plots[[length(plots)+1L]]<-ggplot(dd,aes(group,score,colour=group))+geom_hline(yintercept=0,colour='#DFE5E8',linewidth=.45)+geom_point(position=position_jitter(width=.075,height=0,seed=260914+i),size=2.3,alpha=.95)+stat_summary(fun=median,geom='crossbar',width=.35,colour=ink,linewidth=.4)+scale_colour_manual(values=c(Low=lo,High=hi),guide='none')+scale_x_discrete(labels=c(paste0('Low\nn = ',z$Low),paste0('High\nn = ',z$High)))+scale_y_continuous(expand=expansion(mult=c(.12,.15)))+labs(title=paste0(if(ct=='CD8')'CD8 T cells' else 'cDC1-like cells','\n',lab4[i]),subtitle=paste0('GSEA global q = ',fmt(z$q_global),'\nCAMERA global q = ',fmt(z$CAMERA_q)),x=NULL,y=if(i==1)'Patient pathway score (standardized)' else NULL,caption=paste0('Adjusted High − Low: ',sprintf('%.2f',z$score_beta),'\n95% CI [',sprintf('%.2f',z$score_ci_low),', ',sprintf('%.2f',z$score_ci_high),']\nHC3 score BH q = ',fmt(z$score_q)))+base+theme(plot.title=element_text(size=11.5,lineheight=1.1),plot.subtitle=element_text(size=9),axis.title.y=element_text(size=10),plot.caption=element_text(size=9),plot.margin=margin(10,15,12,8))
}
p2<-wrap_plots(plots,ncol=4)+plot_annotation(title='Patient-level pathway scores within each cell type',subtitle='Same fixed Degradation groups  |  Post-treatment NSCLC  |  Histology-adjusted comparisons',caption='Each point is one patient; bars show unadjusted medians. Effects and 95% intervals use OLS-HC3; score BH includes eight comparisons.\nAll primary score tests are nonsignificant. cDC1-like results are exploratory (111 cells across 10 patients).\nPathway scores are standardized within cell type; absolute levels must not be compared across cell types.',theme=ann)
savefig(p2,'Fig8_CellType_Patient_Pathway_Scores',14.4,9.0)
capture.output(sessionInfo(),file=file.path(out,'logs/sessionInfo_plot.txt'))
